/**
 * チームのまとまり（2026-11-15。前に挙げた案から）: 自分のクラブの主力（序列の上から 8 人）の
 *   長く一緒にいる（このクラブでのシーズン数。5 まで）・今季の入れ替え（シーズンのはじめにいなかった主力。シーズンが進むとなじむ）・選手の気持ち・主将の性格から 0〜100。
 *   効き目: 試合の能力に (まとまり − 50) / 25（−2〜+2。effects.ts の clubMatchBonus）。補強しすぎると下がり、育てて長く使うと上がる。
 *   毎回その場で数える（状態は持たない）。
 */
import type { GameState } from '../models/game'
import type { Player } from '../models/player'
import { clubDepth } from './effects'
import { clubTeam } from './manage'
import { captainOf, moodOf } from './story'
import { townBonus } from './town'

export interface Chemistry {
  value: number
  /** 主力の平均の在籍（シーズン） */
  tenure: number
  /** 今季から入った主力の数 */
  newcomers: number
  /** 主力の気持ちの平均 */
  mood: number
  captain?: Player
  /** 主将の性格・在籍で足した点 */
  captainBonus: number
}

export function chemistry(state: GameState): Chemistry {
  const c = state.club!
  const team = clubTeam(state)
  const core = clubDepth(state)
    .filter((id) => team.roster.includes(id))
    .slice(0, 8)
    .map((id) => state.players[id])
  if (!core.length) return { value: 50, tenure: 0, newcomers: 0, mood: 60, captainBonus: 0 }
  const tenureOf = (p: Player) => Math.min(5, p.history.filter((h) => h.teamId === c.teamId).length)
  const tenure = core.reduce((s, p) => s + tenureOf(p), 0) / core.length
  const start = c.seasonStart?.ovr
  const newcomers = start ? core.filter((p) => start[p.id] === undefined).length : 0
  const mood = core.reduce((s, p) => s + moodOf(state, p.id), 0) / core.length
  const cap = captainOf(state)
  const captainBonus = cap ? (cap.personality === 'leader' ? 8 : cap.personality === 'mood' ? 5 : 2) + (tenureOf(cap) >= 3 ? 4 : 0) : 0
  // 新しく入った主力の減点は、シーズンが進むほど小さく（なじんでくる。第 40 週で 3 割）
  const gel = Math.max(0.3, 1 - state.week / 40)
  const value = Math.round(Math.max(0, Math.min(100, 40 + tenure * 8 - Math.min(25, newcomers * 5) * gel + (mood - 50) * 0.4 + captainBonus + townBonus(state).chemistry)))
  return { value, tenure: Math.round(tenure * 10) / 10, newcomers, mood: Math.round(mood), captain: cap, captainBonus }
}

/** 試合の能力の上乗せ（−2〜+2） */
export function chemistryBonus(state: GameState): number {
  return (chemistry(state).value - 50) / 25
}

export function chemistryLabel(v: number): string {
  return v >= 80 ? 'とても強い' : v >= 60 ? 'よい' : v >= 40 ? 'ふつう' : v >= 25 ? 'ばらばら' : 'ばらばら（危ない）'
}
