/**
 * 今季の目標（キャリア。2026-11-14）: シーズンのはじめに 3〜4 つ（出場時間・プレースタイルに合った成績・チームの順位・NBA の主力ならオールスター）。
 * 目標の数字は、立場（監督の評価）と前のシーズンの成績から（前より少し上）。
 * レギュラーシーズンが終わった週に判定して、ニュースと記録（goals.list の done）に。能力やお金には効かない（目標と手ごたえだけ）。
 */
import { COLLEGE_REGULAR, JBL_REGULAR, NBA_REGULAR } from '../core/calendar'
import { sortedStandings } from '../competition/standings'
import { RULES } from '../data/rules'
import type { GameState } from '../models/game'
import type { LeagueId } from '../models/league'
import type { Player } from '../models/player'

export type GoalKind = 'mpg' | 'ppg' | 'rpg' | 'apg' | 'rank' | 'allstar'

export interface CareerGoal {
  kind: GoalKind
  target: number
  label: string
  /** レギュラーシーズンの終わりに判定（それまでは undefined） */
  done?: boolean
}

export interface CareerGoals {
  season: number
  teamId: number
  list: CareerGoal[]
  /** 判定したか */
  judged?: boolean
}

/** レギュラーシーズンの最後の週 */
export function regularEnd(league: LeagueId): number {
  if (league === 'NCAA') return COLLEGE_REGULAR[1]
  if (league === 'JBL1' || league === 'JBL2' || league === 'JBL3') return JBL_REGULAR[1]
  return NBA_REGULAR[1]
}

const round1 = (v: number) => Math.round(v * 10) / 10

/** 主に伸ばしたい成績（プレースタイルとポジションから） */
function mainStat(p: Player): 'ppg' | 'rpg' | 'apg' {
  if (p.style === 'playmaker' || p.pos === 'PG') return 'apg'
  if (p.style === 'rimProtector' || p.style === 'postScorer' || p.pos === 'C') return 'rpg'
  return 'ppg'
}

const LABEL: Record<'ppg' | 'rpg' | 'apg', string> = { ppg: '点', rpg: 'リバウンド', apg: 'アシスト' }
const BASE: Record<'ppg' | 'rpg' | 'apg', [number, number, number]> = { ppg: [5, 9, 14], rpg: [3, 5, 8], apg: [1.5, 3, 5] }

function perGame(p: Player, kind: 'ppg' | 'rpg' | 'apg' | 'mpg', s = p.stats): number {
  if (s.gp <= 0) return 0
  const v = kind === 'ppg' ? s.pts : kind === 'rpg' ? s.oreb + s.dreb : kind === 'apg' ? s.ast : s.min
  return v / s.gp
}

/** シーズンのはじめ（所属が決まっていて、今季の目標がまだなら）に目標を作る */
export function makeGoals(state: GameState): CareerGoals | null {
  const c = state.career
  if (!c) return null
  const p = state.players[c.playerId]
  if (p.teamId < 0) return null
  const team = state.teams[p.teamId]
  const league = team.league
  // 立場: 0 控え・1 ローテーション・2 先発
  const role = c.trust >= 70 ? 2 : c.trust >= 50 ? 1 : 0
  const gameMin = RULES[state.leagues[league].rules].periodMin * RULES[state.leagues[league].rules].periods
  const mpg = Math.round(([12, 20, 28][role] * gameMin) / 48)
  const stat = mainStat(p)
  const last = p.history[p.history.length - 1]
  const lastVal = last && last.stats.gp >= 10 ? perGame(p, stat, last.stats) : 0
  const target = round1(Math.max(BASE[stat][role], lastVal * 1.12))
  const list: CareerGoal[] = [
    { kind: 'mpg', target: mpg, label: `平均 ${mpg} 分以上出場` },
    { kind: stat, target, label: `平均 ${target} ${LABEL[stat]}` },
  ]
  if (league === 'NBA') list.push({ kind: 'rank', target: 8, label: 'カンファレンス 8 位以内' })
  else if (league === 'NCAA') list.push({ kind: 'rank', target: 16, label: 'リーグ 16 位以内' })
  else if (league !== 'DEV') list.push({ kind: 'rank', target: 8, label: 'リーグ 8 位以内' })
  if (league === 'NBA' && role === 2) list.push({ kind: 'allstar', target: 1, label: 'オールスターに選ばれる' })
  return { season: state.season, teamId: team.id, list }
}

/** チームの順位（NBA はカンファレンスの中） */
function teamRank(state: GameState, teamId: number): number {
  const t = state.teams[teamId]
  const lg = state.leagues[t.league]
  // まだ試合をしていなければ順位はない
  const st = lg.standings[teamId]
  if (!st || st.w + st.l === 0) return 0
  const ids = t.league === 'NBA' ? lg.teamIds.filter((id) => state.teams[id].conf === t.conf) : lg.teamIds
  return sortedStandings(lg, ids).indexOf(teamId) + 1
}

/** いまの値（画面の進み具合） */
export function goalValue(state: GameState, g: CareerGoal, goals: CareerGoals): number {
  const c = state.career!
  const p = state.players[c.playerId]
  if (g.kind === 'rank') return teamRank(state, goals.teamId)
  if (g.kind === 'allstar') return c.allStar === goals.season ? 1 : 0
  return round1(perGame(p, g.kind))
}

/** いま届いているか（順位は小さいほどよい） */
export function goalMet(state: GameState, g: CareerGoal, goals: CareerGoals): boolean {
  const v = goalValue(state, g, goals)
  return g.kind === 'rank' ? v > 0 && v <= g.target : v >= g.target
}

/** 毎週（careerAfterWeek から）: 目標を作る・レギュラーシーズンが終わったら判定する */
export function goalsWeek(state: GameState, playedWeek: number, seasonEnded: boolean) {
  const c = state.career
  if (!c || seasonEnded) return
  const p = state.players[c.playerId]
  if (!c.goals || c.goals.season !== state.season) {
    const g = makeGoals(state)
    if (g) {
      if (c.goals?.judged) c.goalsLast = c.goals
      c.goals = g
    }
    return
  }
  const goals = c.goals
  if (goals.judged || goals.teamId < 0 || !state.teams[goals.teamId]) return
  // 途中で移籍したら、チームの順位は新しいチームで見る
  if (p.teamId >= 0 && p.teamId !== goals.teamId) goals.teamId = p.teamId
  const league = state.teams[goals.teamId].league
  if (playedWeek < regularEnd(league)) return
  // 出場が少なすぎる（10 試合未満）と成績の目標は届かない
  for (const g of goals.list) g.done = (g.kind === 'rank' || g.kind === 'allstar' || p.stats.gp >= 10) && goalMet(state, g, goals)
  goals.judged = true
  const n = goals.list.filter((g) => g.done).length
  state.news.push({ season: state.season, week: playedWeek, text: `${p.name}の今季の目標: ${goals.list.length} つのうち ${n} つ達成${n === goals.list.length ? '（全部達成！）' : ''}`, big: n === goals.list.length })
}
