/**
 * 週間 MVP（2026-11-14）: リーグごとに、その週のレギュラーシーズンの試合でいちばん活躍した選手（1 試合あたりの
 * 得点＋リバウンドとアシストの 0.7 倍＋スティール・ブロック。週に 2 試合以上あるリーグは 2 試合以上出た選手から）。
 * advanceWeek が state.weekly に置き、キャリア（主人公）とクラブ（自分の選手）がニュースと週のまとめに使う。乱数は使わない。
 */
import type { Fixture, LeagueId } from '../models/league'
import type { MatchSummary } from '../match/types'

export interface WeeklyLine {
  pid: number
  gp: number
  pts: number
  reb: number
  ast: number
}

export interface WeeklyMvp {
  season: number
  week: number
  mvp: Partial<Record<LeagueId, WeeklyLine>>
}

export type WeeklyAgg = Map<LeagueId, Map<number, WeeklyLine & { stl: number; blk: number }>>

/** 試合ごとに足す（レギュラーシーズンだけ） */
export function addWeekly(agg: WeeklyAgg, f: Fixture, sum: MatchSummary) {
  if (f.kind !== 'regular') return
  let m = agg.get(f.league)
  if (!m) agg.set(f.league, (m = new Map()))
  for (const [id, b] of Object.entries(sum.box)) {
    if (b.secs <= 0) continue
    const pid = Number(id)
    const x = m.get(pid) ?? { pid, gp: 0, pts: 0, reb: 0, ast: 0, stl: 0, blk: 0 }
    x.gp++
    x.pts += b.pts
    x.reb += b.oreb + b.dreb
    x.ast += b.ast
    x.stl += b.stl
    x.blk += b.blk
    m.set(pid, x)
  }
}

/** 週の終わりに: リーグごとの MVP */
export function pickWeekly(agg: WeeklyAgg, season: number, week: number): WeeklyMvp {
  const mvp: WeeklyMvp['mvp'] = {}
  for (const [league, m] of agg) {
    const lines = [...m.values()]
    const most = Math.max(0, ...lines.map((x) => x.gp))
    const need = most >= 2 ? 2 : 1
    const score = (x: (typeof lines)[number]) => (x.pts + 0.7 * (x.reb + x.ast) + x.stl + x.blk) / x.gp
    const best = lines.filter((x) => x.gp >= need).sort((a, b) => score(b) - score(a) || a.pid - b.pid)[0]
    if (best) mvp[league] = { pid: best.pid, gp: best.gp, pts: best.pts, reb: best.reb, ast: best.ast }
  }
  return { season, week, mvp }
}

/** 「平均 25.5 点・8.0 リバウンド・4.5 アシスト」 */
export function weeklyLineText(x: WeeklyLine): string {
  return `平均 ${(x.pts / x.gp).toFixed(1)} 点・${(x.reb / x.gp).toFixed(1)} リバウンド・${(x.ast / x.gp).toFixed(1)} アシスト`
}
