/**
 * クラブの事業（2026-11-15。ユーザーの「サイドビジネス・施設運営・街づくりもやりたい」。お金は「使い道が中心」）。
 *   開業 → 広げる（Lv3 まで）→ 売る（注ぎ込んだお金の 6 割）。費用はそのときの部の大きさで決まる（BIZ_SCALE）。
 *   毎週の損益 = 注ぎ込んだお金 ×（利回り × 需要 × 景気 − 運営費 2%）/ 52。需要は人気、景気は 8 週ごとに動く。
 *   儲けは控えめ（1 年で注ぎ込んだお金の 2〜4% ほど）で、事業ごとのクラブへの効き目が主（clubBizLevel を各所で読む）。
 *   帳簿は ClubLedger.biz（＋は入り、−は出。開業・拡大は −、売却と毎週の損益は ±）。
 */
import { hashSeed, createRng } from '../core/prng'
import { absWeekOf } from '../core/calendar'
import type { GameState } from '../models/game'
import type { LeagueId } from '../models/league'
import { clubTeam, currentLedger } from './manage'
export { clubBizLevel } from './bizLevel'

export type ClubBizId = 'school' | 'store' | 'media' | 'gym' | 'hotel' | 'estate'

export interface ClubBizDef {
  id: ClubBizId
  name: string
  desc: string
  /** 3 部での開業費（万円）。部が上がると BIZ_SCALE 倍 */
  cost: number
  /** 1 年の利回り（需要 1・景気 1 のとき） */
  rate: number
  /** 景気の受けやすさ（0〜1） */
  cyc: number
  /** Lv ごとのクラブへの効き目（画面の説明） */
  effect: (lv: number) => string
}

export const CLUB_BIZ: ClubBizDef[] = [
  { id: 'school', name: 'バスケスクール', desc: '地元の子どもにバスケを教える。U18 に素質のある子が入ってくる', cost: 1500, rate: 0.04, cyc: 0.4, effect: (lv) => `U18 の新入生の素質 +${lv * 2}` },
  { id: 'store', name: 'クラブショップ・カフェ', desc: 'アリーナの近くのお店。グッズがよく売れる', cost: 2000, rate: 0.05, cyc: 0.8, effect: (lv) => `グッズの売り上げ +${lv * 6}%` },
  { id: 'media', name: 'クラブの動画チャンネル', desc: '練習や裏側を毎週配信する。クラブの人気が上がる', cost: 1000, rate: 0.03, cyc: 0.5, effect: (lv) => `人気の落ち着く先 +${lv * 1.5}` },
  { id: 'gym', name: '地域のジム', desc: '一般向けのジム。選手の体のケアにも使う', cost: 2500, rate: 0.05, cyc: 0.6, effect: (lv) => `ケガ −${lv * 4}%` },
  { id: 'hotel', name: '提携ホテル', desc: '遠征の宿と、アウェイのファンの宿', cost: 4000, rate: 0.04, cyc: 0.9, effect: (lv) => `遠征費 −${lv * 8}%` },
  { id: 'estate', name: 'アリーナ前の不動産', desc: 'アリーナのまわりの店舗とマンション。景気に左右されにくい', cost: 6000, rate: 0.06, cyc: 0.25, effect: () => '安定した収入' },
]
export const CLUB_BIZ_BY_ID = Object.fromEntries(CLUB_BIZ.map((d) => [d.id, d])) as Record<ClubBizId, ClubBizDef>
export const CLUB_BIZ_MAX = 3
/** 部の大きさ（費用の倍率） */
export const BIZ_SCALE: Partial<Record<LeagueId, number>> = { JBL3: 1, JBL2: 2, JBL1: 5, NBA: 40 }
/** 毎年の運営費（注ぎ込んだお金に対して） */
const RUN_COST = 0.02

export interface ClubBiz {
  id: ClubBizId
  level: number
  /** 注ぎ込んだお金（万円） */
  invested: number
  /** 今季の損益（万円） */
  season: number
  /** 通算の損益（万円） */
  total: number
}

const scaleOf = (state: GameState) => BIZ_SCALE[clubTeam(state).league] ?? 1

/** 持っている事業 */
export function clubBiz(state: GameState, id: ClubBizId): ClubBiz | undefined {
  return state.club!.biz?.find((b) => b.id === id)
}

/** 開業・広げる費用（いまの部で） */
export function bizCost(state: GameState, id: ClubBizId): number | null {
  const b = clubBiz(state, id)
  const lv = b?.level ?? 0
  if (lv >= CLUB_BIZ_MAX) return null
  return Math.round(CLUB_BIZ_BY_ID[id].cost * scaleOf(state) * (lv + 1))
}

/** 景気（0.7〜1.3。8 週ごとに動く。同じ週なら同じ） */
export function clubEconomy(state: GameState): number {
  const abs = absWeekOf(state.season, state.week)
  const rng = createRng(hashSeed(state.seed, Math.floor(abs / 8), 0xb12))
  return Math.round(rng.range(0.7, 1.3) * 100) / 100
}

export function economyLabel(e: number): string {
  return e >= 1.15 ? '好景気' : e >= 1.0 ? 'ふつう' : e >= 0.85 ? 'やや不景気' : '不景気'
}

/** 1 週の損益（万円）の見込み */
export function bizWeekly(state: GameState, b: ClubBiz): number {
  const d = CLUB_BIZ_BY_ID[b.id]
  const demand = 0.6 + (state.club!.popularity / 100) * 0.8
  const cycle = 1 + d.cyc * (clubEconomy(state) - 1)
  // 小さな事業は 1 週で 1 万円に満たないので、小数第 1 位まで残す
  return Math.round(((b.invested * (d.rate * demand * cycle - RUN_COST)) / 52) * 10) / 10
}

/** 開業・広げる。うまくいかなければ理由 */
export function growBiz(state: GameState, id: ClubBizId): string | null {
  const c = state.club!
  const cost = bizCost(state, id)
  if (cost === null) return 'これ以上は広げられない'
  if (c.money < cost) return '資金が足りない'
  const list = (c.biz ??= [])
  let b = list.find((x) => x.id === id)
  if (!b) {
    b = { id, level: 0, invested: 0, season: 0, total: 0 }
    list.push(b)
  }
  b.level++
  b.invested += cost
  c.money -= cost
  const l = currentLedger(state)
  l.biz = (l.biz ?? 0) - cost
  state.news.push({ season: state.season, week: state.week, text: b.level === 1 ? `${clubTeam(state).short}が「${CLUB_BIZ_BY_ID[id].name}」を始めた` : `${clubTeam(state).short}の「${CLUB_BIZ_BY_ID[id].name}」を広げた（Lv${b.level}）` })
  return null
}

/** 売る（注ぎ込んだお金の 6 割） */
export function sellBiz(state: GameState, id: ClubBizId): number {
  const c = state.club!
  const b = clubBiz(state, id)
  if (!b) return 0
  const v = bizSellValue(b)
  c.money += v
  c.biz = c.biz!.filter((x) => x.id !== id)
  const l = currentLedger(state)
  l.biz = (l.biz ?? 0) + v
  state.news.push({ season: state.season, week: state.week, text: `「${CLUB_BIZ_BY_ID[id].name}」を売った（${Math.round(v).toLocaleString()} 万円）` })
  return v
}

export const bizSellValue = (b: ClubBiz) => Math.round(b.invested * 0.6)

/** 毎週（clubAfterWeek の帳簿に足す）。シーズンが変わったら今季の損益を 0 に */
export function bizWeek(state: GameState, w: { biz?: number }, seasonEnded: boolean) {
  const c = state.club!
  for (const b of c.biz ?? []) {
    if (seasonEnded) b.season = 0
    const v = bizWeekly(state, b)
    b.season += v
    b.total += v
    w.biz = (w.biz ?? 0) + v
  }
}

/** 1 年の損益の見込み（画面） */
export function bizYearly(state: GameState): number {
  return (state.club!.biz ?? []).reduce((s, b) => s + bizWeekly(state, b) * 52, 0)
}
