/**
 * 主人公の通算の節目（2026-11-14）: 通算 1,000 得点・500 試合出場など。届いた週にニュース（大きな見出し）と記録（career.milestones）。
 * 通算はレギュラーシーズン（経歴＋今季）。毎週、前に確かめた通算（milestoneSeen）と比べて、越えた節目を出す。
 * 古いセーブや二代目のはじめは、今の通算を「確かめた」ことにする（さかのぼって出さない）。
 * 能力やお金には効かない（記録と見出しだけ）。
 */
import type { GameState } from '../models/game'
import type { Player } from '../models/player'

type Kind = 'gp' | 'pts' | 'reb' | 'ast'

export const MILESTONES: Record<Kind, { label: string; unit: string; at: number[] }> = {
  pts: { label: '得点', unit: '得点', at: [500, 1000, 2000, 3000, 5000, 7500, 10000, 12500, 15000, 20000, 25000, 30000] },
  reb: { label: 'リバウンド', unit: 'リバウンド', at: [1000, 2500, 5000, 7500, 10000] },
  ast: { label: 'アシスト', unit: 'アシスト', at: [1000, 2500, 5000, 7500, 10000] },
  gp: { label: '出場', unit: '試合出場', at: [100, 250, 500, 750, 1000, 1250] },
}

const comma = (n: number) => String(n).replace(/\B(?=(\d{3})+(?!\d))/g, ',')

/** 通算（レギュラーシーズン。経歴＋今季） */
export function careerTotals(p: Player): Record<Kind, number> {
  const t = { gp: p.stats.gp, pts: p.stats.pts, reb: p.stats.oreb + p.stats.dreb, ast: p.stats.ast }
  for (const h of p.history) {
    t.gp += h.stats.gp
    t.pts += h.stats.pts
    t.reb += h.stats.oreb + h.stats.dreb
    t.ast += h.stats.ast
  }
  return t
}

/** 次の節目（画面の「あと ○ で通算 ○ 得点」） */
export function nextMilestone(p: Player, kind: Kind): { at: number; left: number } | null {
  const v = careerTotals(p)[kind]
  const at = MILESTONES[kind].at.find((x) => x > v)
  return at === undefined ? null : { at, left: at - v }
}

/** 毎週（careerAfterWeek から。season・week は進めた週）。越えた節目をニュースと記録に。出した節目の文を返す */
export function milestonesWeek(state: GameState, season: number, week: number): string[] {
  const c = state.career
  if (!c) return []
  const p = state.players[c.playerId]
  const now = careerTotals(p)
  const seen = c.milestoneSeen
  c.milestoneSeen = now
  if (!seen) return []
  const out: string[] = []
  for (const kind of Object.keys(MILESTONES) as Kind[]) {
    const m = MILESTONES[kind]
    for (const at of m.at) {
      if (seen[kind] < at && now[kind] >= at) {
        const text = kind === 'gp' ? `通算 ${comma(at)} 試合出場` : `通算 ${comma(at)} ${m.unit}`
        out.push(text)
        ;(c.milestones ??= []).push({ season, week, text })
        state.news.push({ season, week, text: `${p.name}が${text}に到達！`, big: true })
      }
    }
  }
  return out
}
