export const TOWN_PROJECT_BY_ID = Object.fromEntries(TOWN_PROJECTS.map((p) => [p.id, p])) as Record<string, TownProject>

export const TOWN_SCALE: Partial<Record<LeagueId, number>> = { JBL3: 1, JBL2: 2, JBL1: 4, NBA: 25 }
export const TOWN_MAX_LV = 3
/** レベルごとの費用の倍率（その段に上げるとき）・週の倍率・指標の上がり方（Lv1 からの合計）・上乗せの倍率 */
const LV_COST = [0, 1, 2, 4]
const LV_WEEKS = [0, 1, 1.5, 2]
const LV_GAIN = [0, 1, 1.6, 2.2]
const LV_PERK = [0, 1, 1.5, 2]
/** 毎年の維持費（注ぎ込んだ費用に対して） */
const UPKEEP_RATE = 0.04
const LEAGUE_RANK: Record<string, number> = { JBL3: 0, JBL2: 1, JBL1: 2, NBA: 3 }
const LEAGUE_LABEL: Record<string, string> = { JBL2: '2 部', JBL1: '1 部', NBA: 'NBA' }

/** 街のランク（townLevel 1〜5） */
export const TOWN_RANKS = ['静かな町', 'バスケが好きな町', 'バスケの町', 'バスケの街', 'バスケの聖地'] as const

export interface TownState {
  /** 建てた計画（id → 注ぎ込んだ費用の合計） */
  built: Record<string, number>
  /** 計画のレベル（なければ建ててあれば 1） */
  lv?: Record<string, number>
  /** 建てている計画（終わる絶対週・上げるレベル。lv がなければ 1） */
  building?: { id: string; doneAbs: number; paid: number; lv?: number }
  /** これまでにいちばん上がった街のランク（ニュースを 1 回だけ出す） */
  rank?: number
}

/** いまのホームタウンの街（なければ作る） */
export function townOf(state: GameState): TownState {
  const c = state.club!
  const all = (c.towns ??= {})
  return (all[c.hometown] ??= { built: {} })
}

const townNow = (state: GameState): TownState | undefined => state.club?.towns?.[state.club.hometown]

/** 計画のいまのレベル（建てていなければ 0） */
export function projectLv(state: GameState, id: string): number {
  const t = townNow(state)
  if (!t || t.built[id] === undefined) return 0
  return t.lv?.[id] ?? 1
}

/** 街の指標のはじめの値（ホームタウンの熱と人口から） */
export function townBase(state: GameState): Record<TownStat, number> {
  const home = HOMETOWN_BY_ID[state.club!.hometown]
  return { hoops: 15 + home.passion * 5, buzz: Math.round(10 + Math.min(20, home.pop / 5)), living: 30 }
}

/** 全部の計画を Lv3 にしたときの、指標ごとの上がり方の合計 */
const RAW_MAX: Record<TownStat, number> = { hoops: 0, buzz: 0, living: 0 }
for (const p of TOWN_PROJECTS) for (const k of Object.keys(p.gain) as TownStat[]) RAW_MAX[k] += p.gain[k]! * LV_GAIN[TOWN_MAX_LV]
const STAT_CURVE = 1.6

/** 街の指標（0〜100）。over で計画のレベルを差し替えて数える（画面の「建てるとどれだけ上がるか」） */
export function townStats(state: GameState, over?: { id: string; lv: number }): Record<TownStat, number> {
  const s = townBase(state)
  const t = townNow(state)
  const raw: Record<TownStat, number> = { hoops: 0, buzz: 0, living: 0 }
  const ids = new Set(Object.keys(t?.built ?? {}))
  if (over) ids.add(over.id)
  for (const id of ids) {
    const p = TOWN_PROJECT_BY_ID[id]
    if (!p) continue
    const lv = over?.id === id ? over.lv : projectLv(state, id)
    const m = LV_GAIN[lv] ?? 0
    for (const k of Object.keys(p.gain) as TownStat[]) raw[k] += p.gain[k]! * m
  }
  for (const k of Object.keys(s) as TownStat[]) {
    const f = Math.min(1, raw[k] / RAW_MAX[k])
    s[k] = Math.min(100, Math.round(s[k] + (100 - s[k]) * (1 - (1 - f) ** STAT_CURVE)))
  }
  return s
}

/** その計画をそのレベルにしたときの指標の上がり方（いまとの差。lv = 0 ならその計画がないときとの差＝いまの効き目） */
export function projectDelta(state: GameState, id: string, lv: number): Partial<Record<TownStat, number>> {
  const cur = projectLv(state, id)
  const a = townStats(state, lv === 0 ? { id, lv: 0 } : { id, lv: cur })
  const b = townStats(state, lv === 0 ? { id, lv: cur } : { id, lv })
  const out: Partial<Record<TownStat, number>> = {}
  for (const k of Object.keys(a) as TownStat[]) if (b[k] - a[k] > 0) out[k] = b[k] - a[k]
  return out
}

/** 指標の平均 */
export function townAverage(state: GameState): number {
  const s = townStats(state)
  return (s.hoops + s.buzz + s.living) / 3
}

/** 街のランクに上がる指標の平均 */
export const TOWN_RANK_AT = [0, 30, 45, 65, 90]

/** 街のレベル（1〜5。指標の平均から） */
export function townLevel(state: GameState): number {
  const avg = townAverage(state)
  return TOWN_RANK_AT.filter((x) => avg >= x).length
}

/** 街のランクの名前と、次のランクまでの進み具合（0〜1。いちばん上なら 1） */
export function townRank(state: GameState): { level: number; name: string; next?: string; progress: number } {
  const avg = townAverage(state)
  const level = townLevel(state)
  if (level >= 5) return { level, name: TOWN_RANKS[4], progress: 1 }
  const lo = TOWN_RANK_AT[level - 1]
  const hi = TOWN_RANK_AT[level]
  return { level, name: TOWN_RANKS[level - 1], next: TOWN_RANKS[level], progress: Math.max(0, Math.min(1, (avg - lo) / (hi - lo))) }
}

/** 計画ごとの上乗せ（Lv の倍率を掛けたもの） */
export function projectPerks(id: string, lv: number): TownPerk[] {
  const p = TOWN_PROJECT_BY_ID[id]
  return (p?.perks ?? []).map((x) => ({ kind: x.kind, v: x.v * (LV_PERK[lv] ?? 1) }))
}

const NO_BONUS = { attendance: 1, ticket: 1, goods: 1, sponsor: 1, fanCeiling: 0, fanGrowth: 1, popularity: 0, youthPot: 0, chemistry: 0 }
export type TownBonus = typeof NO_BONUS

/**
 * 効き目（ほかのところから読む）。はじめの値から上がったぶんだけ効く（計画を建てなければ前と同じ）
 *   指標から: 観客 +0.15%/にぎわい・スポンサー +0.25%/にぎわい・ファンの天井 +人口の 20% × バスケ人気の上がり（6 万人まで）・
 *   ファンの増え方 +0.6%/暮らしやすさ・人気 +1/暮らしやすさ 25・U18 の素質 +1/バスケ人気 40。そこに計画ごとの上乗せ
 */
export function townBonus(state: GameState): TownBonus {
  const c = state.club
  const t = c ? townNow(state) : undefined
  if (!c || !t || Object.keys(t.built).length === 0) return NO_BONUS
  const s = townStats(state)
  const b = townBase(state)
  const d = { hoops: s.hoops - b.hoops, buzz: s.buzz - b.buzz, living: s.living - b.living }
  const home = HOMETOWN_BY_ID[c.hometown]
  const add: Record<PerkKind, number> = { attendance: 0, ticket: 0, goods: 0, sponsor: 0, popularity: 0, youthPot: 0, chemistry: 0, fanGrowth: 0 }
  for (const id of Object.keys(t.built)) for (const x of projectPerks(id, projectLv(state, id))) add[x.kind] += x.v
  return {
    /** 観客の倍率（にぎわい・送迎バス・駐車場など） */
    attendance: (1 + d.buzz * 0.0015) * (1 + add.attendance),
    /** 入場料の倍率（屋台通り） */
    ticket: 1 + add.ticket,
    /** グッズの倍率（商店街とのコラボ・アーケード・博物館） */
    goods: 1 + add.goods,
    /** スポンサーの相場の倍率（にぎわい・再開発など） */
    sponsor: (1 + d.buzz * 0.0025) * (1 + add.sponsor),
    /** ファンの天井に足す人数（バスケ人気。NBA では使わない） */
    fanCeiling: Math.min(60000, Math.round(home.pop * 10000 * 0.2 * (Math.max(0, d.hoops) / 100))),
    /** ファンの増え方の倍率（暮らしやすさ・パブリックビューイングなど） */
    fanGrowth: (1 + d.living * 0.006) * (1 + add.fanGrowth),
    /** 人気の落ち着く先に足す（暮らしやすさ・見守りなど） */
    popularity: d.living / 25 + add.popularity,
    /** U18 の素質に足す（バスケ人気・学校） */
    youthPot: d.hoops / 40 + add.youthPot,
    /** チームのまとまりに足す（選手寮。chemistry.ts） */
    chemistry: add.chemistry,
  }
}

const scaleOf = (state: GameState) => TOWN_SCALE[clubTeam(state).league] ?? 1

/** 次に建てる段（建てていなければ 1。いちばん上なら undefined） */
export function nextLv(state: GameState, id: string): number | undefined {
  const lv = projectLv(state, id)
  return lv >= TOWN_MAX_LV ? undefined : lv + 1
}

/** 計画の費用（いまの部で。lv を省くと次の段） */
export function projectCost(state: GameState, id: string, lv?: number): number {
  const to = lv ?? nextLv(state, id) ?? TOWN_MAX_LV
  return Math.round(TOWN_PROJECT_BY_ID[id].cost * (LV_COST[to] ?? 1) * scaleOf(state))
}

/** 計画にかかる週（lv を省くと次の段） */
export function projectWeeks(state: GameState, id: string, lv?: number): number {
  const to = lv ?? nextLv(state, id) ?? TOWN_MAX_LV
  return Math.round(TOWN_PROJECT_BY_ID[id].weeks * (LV_WEEKS[to] ?? 1))
}

/** 建てられない（次の段に上げられない）理由（なければ null） */
export function projectProblem(state: GameState, id: string): string | null {
  const p = TOWN_PROJECT_BY_ID[id]
  const t = townOf(state)
  const to = nextLv(state, id)
  if (t.building?.id === id) return '建てている'
  if (!to) return 'いちばん大きい'
  if (t.building) return 'ほかの計画を建てている'
  const rank = LEAGUE_RANK[clubTeam(state).league] ?? 0
  if (to === 1) {
    if (p.needs && t.built[p.needs] === undefined) return `先に「${TOWN_PROJECT_BY_ID[p.needs].name}」を`
    if (p.minLeague && rank < LEAGUE_RANK[p.minLeague]) return `${LEAGUE_LABEL[p.minLeague]}に上がってから`
  }
  if (to === 3 && rank < LEAGUE_RANK.JBL1) return 'Lv3 は 1 部に上がってから'
  if (state.club!.money < projectCost(state, id)) return '資金が足りない'
  return null
}

/** 建て始める・次の段に広げ始める（費用はその場で、帳簿の工事に） */
export function startProject(state: GameState, id: string): string | null {
  const why = projectProblem(state, id)
  if (why) return why
  const c = state.club!
  const p = TOWN_PROJECT_BY_ID[id]
  const lv = nextLv(state, id)!
  const cost = projectCost(state, id)
  const weeks = projectWeeks(state, id)
  c.money -= cost
  currentLedger(state).build += cost
  // 街のランクは建て始める前の段を覚えておき、上がったときだけ知らせる
  townOf(state).rank ??= townLevel(state)
  townOf(state).building = { id, doneAbs: absWeekOf(state.season, state.week) + weeks, paid: cost, lv }
  const city = HOMETOWN_BY_ID[c.hometown].city
  state.news.push({ season: state.season, week: state.week, text: lv === 1 ? `${city}で「${p.name}」の計画が始まった（${weeks} 週）` : `${city}の「${p.name}」を Lv${lv} に広げる工事が始まった（${weeks} 週）` })
  return null
}

/** 毎週（clubAfterWeek から）: 建て終わった計画を街に足す。街のランクが上がったらニュースと人気。終わった計画の名前を返す */
export function townWeek(state: GameState): string | null {
  const c = state.club!
  const t = townNow(state)
  const b = t?.building
  if (!t || !b || absWeekOf(state.season, state.week) < b.doneAbs) return null
  const lv = b.lv ?? 1
  t.built[b.id] = (t.built[b.id] ?? 0) + b.paid
  ;(t.lv ??= {})[b.id] = lv
  delete t.building
  const name = TOWN_PROJECT_BY_ID[b.id]?.name ?? ''
  const city = HOMETOWN_BY_ID[c.hometown].city
  state.news.push({ season: state.season, week: state.week, text: lv === 1 ? `${city}の「${name}」ができた！` : `${city}の「${name}」が Lv${lv} になった！`, big: true })
  const level = townLevel(state)
  if (level > (t.rank ?? level)) {
    c.popularity = Math.min(100, c.popularity + 2)
    state.news.push({ season: state.season, week: state.week, text: `${city}が「${TOWN_RANKS[level - 1]}」になった！ 街中がクラブを応援している（人気 +2）`, big: true })
  }
  t.rank = Math.max(t.rank ?? level, level)
  return name
}

/** 毎年の街の維持費（万円。いまのホームタウンに注ぎ込んだ費用の 4%） */
export function townUpkeep(state: GameState): number {
  const t = townNow(state)
  return Math.round(Object.values(t?.built ?? {}).reduce((s, v) => s + v * UPKEEP_RATE, 0))
}

/** マップの区画: 地区ごとの計画（並びは TOWN_PROJECTS の順） */
export function districtProjects(district: DistrictId): TownProject[] {
  return TOWN_PROJECTS.filter((p) => p.district === district)
}
