/**
 * レンタル移籍（期限付き移籍。2026-11-15。前に挙げた案から）: 国内リーグのクラブのあいだで、シーズンの終わりまで選手を貸し借りする。
 *   貸し出す: 自分の 24 歳までの選手（契約が 2 年以上残っている・ケガをしていない）を、同じか下の部のクラブへ。
 *     いちばん出番のありそうなクラブ（入れば何番手かがいちばん上）に決まる。年俸は半分を自分のクラブが払い続ける。
 *   借りる: 同じか上の部のクラブの 24 歳までの控え（そのクラブの 9 番手より下）を、入れば 9 番手より上に入るなら。年俸の半分を払う。
 *     借りるときにレンタル料（年俸の 3 割。LOAN_FEE_SHARE）を元のクラブへ払う（安く強い選手が借りられすぎないように）。
 *   シーズンの終わり（clubSeasonEnd の最後。経歴はもう記録されている）に元のクラブへ戻る。
 *   レンタル中の選手は売り買い・解除ができない。AI のクラブが人数合わせで放そうとしたときは、放さずに元のクラブへ戻す（freeAgency.ts の releasePlayer）。
 *   NBA に入ったクラブはレンタルしない（NBA の決まりがちがう）。貸し出し 3 人・借りる 2 人まで。移籍の期間だけ。
 */
import { ageAt } from '../core/calendar'
import type { GameState } from '../models/game'
import type { LeagueId, Team } from '../models/league'
import type { Player } from '../models/player'
import { ovr } from '../player/overall'
import { nowAbs } from '../query'
import { ROSTER_LIMIT } from '../gen/worldGen'
import { clubTeam, currentLedger } from './manage'
import { quotaProblem, slotOf, windowOpen } from './transfer'

export const LOAN_OUT_MAX = 3
export const LOAN_IN_MAX = 2
export const LOAN_AGE_MAX = 24
export const LOAN_FEE_SHARE = 0.3

/** 借りるときのレンタル料（万円。10 万円単位） */
export function loanFee(p: Player): number {
  return Math.round((p.contract.salary * LOAN_FEE_SHARE) / 10) * 10
}
const TIER: Record<string, number> = { JBL1: 1, JBL2: 2, JBL3: 3 }
const SLOT_MAX = (league: LeagueId, s: 'asia' | 'foreign') => (s === 'asia' ? 1 : league === 'JBL3' ? 2 : 3)

/** その選手がそのチームに入ったら何番手か（総合値の順） */
function rankIn(state: GameState, t: Team, p: Player): number {
  const o = ovr(p)
  return 1 + t.roster.filter((id) => id !== p.id && ovr(state.players[id]) > o).length
}

/** 相手のチームに入れるか（人数と外国籍・アジア枠） */
function fits(state: GameState, t: Team, p: Player): boolean {
  if (t.roster.length >= (ROSTER_LIMIT[t.league] ?? 13)) return false
  const s = slotOf(p)
  if (s === 'jp') return true
  return t.roster.filter((id) => slotOf(state.players[id]) === s).length < SLOT_MAX(t.league, s)
}

const ageOfP = (state: GameState, p: Player) => ageAt(nowAbs(state), p.birthAbs)

/** レンタルできる状態か（自分のクラブ） */
function clubProblem(state: GameState): string | null {
  if (!state.club) return 'クラブ経営だけ'
  if (clubTeam(state).league === 'NBA') return 'NBA ではレンタルしない'
  if (!windowOpen(state)) return '移籍の期間だけ（登録の締め切りまで）'
  return null
}

/** 貸し出せない理由（なければ null） */
export function loanOutProblem(state: GameState, p: Player): string | null {
  const why = clubProblem(state)
  if (why) return why
  const c = state.club!
  const team = clubTeam(state)
  if (!team.roster.includes(p.id)) return '自分の選手ではない'
  if (p.loan) return 'レンタル中'
  if (ageOfP(state, p) > LOAN_AGE_MAX) return `${LOAN_AGE_MAX} 歳まで`
  if (p.contract.years < 2) return '契約が 2 年以上残っている選手だけ'
  if (p.injury) return 'ケガをしている'
  if (c.listed?.includes(p.id)) return '売りに出している'
  if ((c.loanOut ?? []).length >= LOAN_OUT_MAX) return `貸し出しは ${LOAN_OUT_MAX} 人まで`
  if (team.roster.length <= 10) return '登録が 10 人を切ってしまう'
  return null
}

/** 貸し出し先（同じか下の部で、入れば何番手かがいちばん上のクラブ）。いなければ undefined */
export function loanDestination(state: GameState, p: Player): { team: Team; rank: number } | undefined {
  const me = clubTeam(state)
  const myTier = TIER[me.league] ?? 3
  let best: { team: Team; rank: number } | undefined
  for (const lg of ['JBL1', 'JBL2', 'JBL3'] as LeagueId[]) {
    if ((TIER[lg] ?? 3) < myTier) continue
    for (const id of state.leagues[lg].teamIds) {
      const t = state.teams[id]
      if (t.id === me.id || !fits(state, t, p)) continue
      const rank = rankIn(state, t, p)
      if (!best || rank < best.rank || (rank === best.rank && (TIER[t.league] ?? 3) < (TIER[best.team.league] ?? 3))) best = { team: t, rank }
    }
  }
  return best
}

/** 貸し出す */
export function loanOut(state: GameState, playerId: number): string | null {
  const p = state.players[playerId]
  const why = loanOutProblem(state, p)
  if (why) return why
  const dest = loanDestination(state, p)
  if (!dest) return '貸し出せるクラブがない'
  const c = state.club!
  const me = clubTeam(state)
  me.roster = me.roster.filter((id) => id !== p.id)
  dest.team.roster.push(p.id)
  p.teamId = dest.team.id
  p.loan = { owner: me.id }
  ;(c.loanOut ??= []).push(p.id)
  state.news.push({ season: state.season, week: state.week, text: `${p.name}が${dest.team.name}へレンタル移籍（シーズンの終わりまで）` })
  return null
}

/** 借りられる選手（同じか上の部のクラブの 24 歳までの控えで、入れば 9 番手より上） */
export function loanInCandidates(state: GameState): Player[] {
  if (clubProblem(state)) return []
  const me = clubTeam(state)
  const myTier = TIER[me.league] ?? 3
  const out: Player[] = []
  for (const lg of ['JBL1', 'JBL2', 'JBL3'] as LeagueId[]) {
    if ((TIER[lg] ?? 3) > myTier) continue
    for (const id of state.leagues[lg].teamIds) {
      const t = state.teams[id]
      if (t.id === me.id) continue
      const ranked = [...t.roster].sort((a, b) => ovr(state.players[b]) - ovr(state.players[a]))
      ranked.forEach((pid, i) => {
        const p = state.players[pid]
        if (i < 8 || p.loan || p.castId || p.injury || ageOfP(state, p) > LOAN_AGE_MAX || p.contract.years < 1) return
        if (rankIn(state, me, p) > 9) return
        out.push(p)
      })
    }
  }
  return out.sort((a, b) => ovr(b) - ovr(a))
}

/** 借りられない理由 */
export function loanInProblem(state: GameState, p: Player): string | null {
  const why = clubProblem(state)
  if (why) return why
  if ((state.club!.loanIn ?? []).length >= LOAN_IN_MAX) return `借りるのは ${LOAN_IN_MAX} 人まで`
  if (!loanInCandidates(state).some((x) => x.id === p.id)) return 'この選手は借りられない'
  if (state.club!.money < loanFee(p)) return 'レンタル料が払えない'
  return quotaProblem(state, p)
}

/** 借りる */
export function loanIn(state: GameState, playerId: number): string | null {
  const p = state.players[playerId]
  const why = loanInProblem(state, p)
  if (why) return why
  const c = state.club!
  const me = clubTeam(state)
  const from = state.teams[p.teamId]
  const fee = loanFee(p)
  c.money -= fee
  currentLedger(state).transfer -= fee
  from.roster = from.roster.filter((id) => id !== p.id)
  me.roster.push(p.id)
  p.teamId = me.id
  p.loan = { owner: from.id }
  ;(c.loanIn ??= []).push(p.id)
  state.news.push({ season: state.season, week: state.week, text: `${from.name}の${p.name}をレンタルで獲得（シーズンの終わりまで・レンタル料 ${fee.toLocaleString()} 万円）` })
  return null
}

/** 元のクラブへ戻す（シーズンの終わり・AI が放そうとしたとき） */
export function returnLoan(state: GameState, p: Player) {
  const owner = p.loan ? state.teams[p.loan.owner] : undefined
  const cur = state.teams[p.teamId]
  if (cur) cur.roster = cur.roster.filter((id) => id !== p.id)
  delete p.loan
  const c = state.club
  if (c) {
    c.loanOut = (c.loanOut ?? []).filter((id) => id !== p.id)
    c.loanIn = (c.loanIn ?? []).filter((id) => id !== p.id)
  }
  if (owner) {
    owner.roster.push(p.id)
    p.teamId = owner.id
  } else {
    p.teamId = -1
    p.contract = { salary: 0, years: 0, kind: 'none' }
  }
}

/** シーズンの終わり（clubSeasonEnd の最後）: レンタルの選手を元のクラブへ。ニュースに今季の成績 */
export function loanSeasonEnd(state: GameState) {
  const c = state.club!
  for (const id of [...(c.loanOut ?? []), ...(c.loanIn ?? [])]) {
    const p = state.players[id]
    if (!p?.loan) continue
    const out = (c.loanOut ?? []).includes(id)
    const h = p.history.find((x) => x.season === state.season)
    const line = h && h.stats.gp > 0 ? `（${h.stats.gp} 試合・平均 ${(h.stats.pts / h.stats.gp).toFixed(1)} 点）` : ''
    returnLoan(state, p)
    state.news.push({ season: state.season, week: state.week, text: out ? `${p.name}がレンタルから戻ってきた${line}` : `${p.name}がレンタルを終えて元のクラブへ戻った${line}` })
  }
}

/** 年俸のうち自分のクラブが払うぶん（貸し出し・借りるとも半分）。manage.ts の payrollOf から */
export function loanPayrollAdjust(state: GameState): number {
  const c = state.club!
  const out = (c.loanOut ?? []).reduce((s, id) => s + (state.players[id]?.contract.salary ?? 0) * 0.5, 0)
  const inn = (c.loanIn ?? []).reduce((s, id) => s - (state.players[id]?.contract.salary ?? 0) * 0.5, 0)
  return out + inn
}
