/** 状態から引くよく使う値。 */
import { ageAt, absWeekOf } from './core/calendar'
import type { GameState } from './models/game'
import type { Team } from './models/league'
import type { Player } from './models/player'
import { ovr } from './player/overall'

export function nowAbs(state: GameState): number {
  return absWeekOf(state.season, state.week)
}

export function ageOf(state: GameState, p: Player): number {
  return ageAt(nowAbs(state), p.birthAbs)
}

export function teamOf(state: GameState, p: Player): Team | undefined {
  return p.teamId >= 0 ? state.teams[p.teamId] : undefined
}

export function rosterOf(state: GameState, team: Team): Player[] {
  return team.roster.map((id) => state.players[id])
}

export function teamsOf(state: GameState, league: keyof GameState['leagues']): Team[] {
  return state.leagues[league].teamIds.map((id) => state.teams[id])
}

/** 外国籍か（国内リーグの外国籍枠の判定。日本以外はすべて） */
export function isForeign(p: Player): boolean {
  return p.nation !== 'JP'
}

/** チームの戦力（上位 8 人の総合値の平均） */
export function teamPower(state: GameState, t: Team): number {
  const v = rosterOf(state, t)
    .map((p) => ovr(p))
    .sort((a, b) => b - a)
    .slice(0, 8)
  return v.length ? v.reduce((s, x) => s + x, 0) / v.length : 0
}

/** 直近の試合の勝ち負け（今季の日程。古い順に n 試合）と、最後に続いている連勝・連敗（2026-11-14） */
export function recentForm(state: GameState, teamId: number, n = 5): { results: boolean[]; streak: number; win: boolean } {
  const all = state.fixtures
    .filter((f) => f.result && (f.home === teamId || f.away === teamId))
    .sort((a, b) => a.week - b.week || a.day - b.day || a.id - b.id)
    .map((f) => (f.home === teamId ? f.result!.hs > f.result!.as : f.result!.as > f.result!.hs))
  let streak = 0
  const last = all[all.length - 1]
  for (let i = all.length - 1; i >= 0 && all[i] === last; i--) streak++
  return { results: all.slice(-n), streak, win: !!last }
}

/** 次の試合（今週より後の、まだ結果のない試合でいちばん早いもの。試合のない週の「次の試合まで」） */
export function nextFixture(state: GameState, teamId: number): { week: number; in: number; opp: number } | null {
  if (teamId < 0) return null
  let best: { week: number; day: number; opp: number } | null = null
  for (const f of state.fixtures) {
    if (f.result || f.week <= state.week || (f.home !== teamId && f.away !== teamId)) continue
    if (!best || f.week < best.week || (f.week === best.week && f.day < best.day)) best = { week: f.week, day: f.day, opp: f.home === teamId ? f.away : f.home }
  }
  return best ? { week: best.week, in: best.week - state.week, opp: best.opp } : null
}
