/**
 * ダービー（2026-11-15。前に挙げた案から）: 自分のクラブの宿敵。同じ部の、同じ地方（なければいちばん近い地方）のクラブ。
 *   地方は街の名前から（REGION_OF）。同じ地方に何クラブかあれば、格（rep）が自分の格にいちばん近いクラブ。NBA では同じディビジョンでいちばん格の高いチーム。
 *   宿敵との試合は「ダービー」: 観客 ×1.35、勝てば人気 +1.5・ファン +1%、負けると人気 −0.5。通算の対戦成績を残す（club.derbyRec）。
 *   部が変われば相手も変わる（毎回いまの部から決める）。
 */
import { HOMETOWN_BY_ID } from '../data/club'
import type { GameState } from '../models/game'
import type { Fixture, Team } from '../models/league'
import { clubTeam } from './manage'

const REGIONS = ['北海道', '東北', '関東', '中部', '近畿', '中国', '四国', '九州'] as const
type Region = (typeof REGIONS)[number]

const CITIES: Record<Region, string[]> = {
  北海道: ['札幌', '函館', '旭川', '釧路', '帯広', '北見', '網走'],
  東北: ['仙台', '秋田', '盛岡', '青森', '郡山', '八戸', '山形', '鶴岡', '酒田', '米沢'],
  関東: ['東京', '横浜', '千葉', 'さいたま', '川崎', '前橋', '水戸', '宇都宮', '高崎', '船橋', '八王子', '市川', '八千代', '習志野', '町田', '立川', '日野'],
  中部: ['名古屋', '新潟', '静岡', '金沢', '長野', '富山', '甲府', '岐阜', '浜松', '豊田', '福井', '上越', '刈谷', '岡崎', '豊橋', '坂井', '越前', '敦賀'],
  近畿: ['大阪', '神戸', '京都', '奈良', '津', '和歌山', '堺', '姫路', '大津', '加古川', '明石', 'たつの', '和泉', '岸和田', '富田林', '彦根', '草津', '守山'],
  中国: ['広島', '岡山', '鳥取', '松江', '下関'],
  四国: ['松山', '高松', '徳島', '高知'],
  九州: ['福岡', '沖縄', '熊本', '鹿児島', '佐世保', '大分', '北九州', '長崎', '宮崎', '大村', '島原', '諫早', '宗像', '行橋', '飯塚', '延岡', '日向', '都城'],
}
const REGION_OF: Record<string, Region> = Object.fromEntries(REGIONS.flatMap((r) => CITIES[r].map((c) => [c, r])))

/** チームの地方（分からなければ undefined） */
function regionOfTeam(state: GameState, t: Team): Region | undefined {
  if (state.club && t.id === state.club.teamId) {
    const city = HOMETOWN_BY_ID[state.club.hometown]?.city
    if (city && REGION_OF[city]) return REGION_OF[city]
  }
  return REGION_OF[t.city]
}

const dist = (a?: Region, b?: Region) => (a && b ? Math.abs(REGIONS.indexOf(a) - REGIONS.indexOf(b)) : 9)

/** いまの宿敵（いなければ undefined） */
export function derbyRival(state: GameState): Team | undefined {
  const c = state.club
  if (!c) return undefined
  const me = clubTeam(state)
  const others = state.leagues[me.league].teamIds.filter((id) => id !== me.id).map((id) => state.teams[id])
  if (!others.length) return undefined
  if (me.league === 'NBA') {
    const div = others.filter((t) => t.div === me.div)
    return [...(div.length ? div : others)].sort((a, b) => b.rep - a.rep || a.id - b.id)[0]
  }
  const mine = regionOfTeam(state, me)
  return [...others].sort((a, b) => dist(mine, regionOfTeam(state, a)) - dist(mine, regionOfTeam(state, b)) || Math.abs(a.rep - me.rep) - Math.abs(b.rep - me.rep) || a.id - b.id)[0]
}

/** その試合がダービーか */
export function isDerby(state: GameState, f: Fixture): boolean {
  const c = state.club
  if (!c || (f.home !== c.teamId && f.away !== c.teamId)) return false
  const r = derbyRival(state)
  return !!r && (f.home === r.id || f.away === r.id)
}

/** ダービーの観客の倍率 */
export const DERBY_CROWD = 1.35

/** ダービーの結果（clubAfterWeek から）: 人気・ファン・対戦成績・ニュース */
export function derbyResult(state: GameState, opp: Team, won: boolean) {
  const c = state.club!
  const rec = ((c.derbyRec ??= {})[opp.id] ??= { w: 0, l: 0 })
  if (won) rec.w++
  else rec.l++
  c.popularity = Math.max(1, Math.min(100, c.popularity + (won ? 1.5 : -0.5)))
  state.news.push({ season: state.season, week: state.week, text: won ? `ダービーで${opp.short}に勝った！ 街が沸いている（通算 ${rec.w} 勝 ${rec.l} 敗）` : `ダービーで${opp.short}に敗れた（通算 ${rec.w} 勝 ${rec.l} 敗）`, big: won })
}

/** 宿敵との通算の対戦成績 */
export function derbyRecord(state: GameState, teamId: number): { w: number; l: number } {
  return state.club?.derbyRec?.[teamId] ?? { w: 0, l: 0 }
}
