/**
 * クラブ記録（2026-11-14）: 自分のクラブの試合（レギュラーシーズン・プレーオフ・全日本選手権）での
 * 1 試合のチームの最多得点・選手の最多得点・リバウンド・アシスト、いちばん長い連勝（レギュラーシーズン）。
 * 記録と、週のまとめの「クラブ新記録」だけ（ほかには効かない）。
 */
import type { GameState } from '../models/game'
import type { Fixture } from '../models/league'
import type { MatchSummary } from '../match/types'

export interface ClubRecord {
  v: number
  season: number
  week: number
  /** 選手の名前（チームの記録は相手の名前） */
  who: string
}

export interface ClubRecords {
  teamPts?: ClubRecord
  playerPts?: ClubRecord
  playerReb?: ClubRecord
  playerAst?: ClubRecord
  streak?: ClubRecord
}

export const CLUB_RECORD_LABEL: Record<keyof ClubRecords, string> = {
  teamPts: 'チームの最多得点',
  playerPts: '選手の最多得点',
  playerReb: '選手の最多リバウンド',
  playerAst: '選手の最多アシスト',
  streak: 'いちばん長い連勝',
}

function bump(r: ClubRecords, k: keyof ClubRecords, v: number, state: GameState, who: string) {
  const cur = r[k]
  if (v > 0 && (!cur || v > cur.v)) r[k] = { v, season: state.season, week: state.week, who }
}

/** 試合の結果を入れたあと（results.ts の applyResult から）。自分のクラブの試合だけ */
export function clubRecordGame(state: GameState, f: Fixture, sum: MatchSummary) {
  const c = state.club
  if (!c || (f.home !== c.teamId && f.away !== c.teamId)) return
  const r = (c.records ??= {})
  const home = f.home === c.teamId
  const opp = state.teams[home ? f.away : f.home]
  bump(r, 'teamPts', home ? sum.score[0] : sum.score[1], state, opp?.name ?? '')
  const mine = new Set(state.teams[c.teamId].roster)
  for (const [id, b] of Object.entries(sum.box)) {
    if (!mine.has(Number(id)) || b.secs <= 0) continue
    const name = state.players[Number(id)]?.name ?? ''
    bump(r, 'playerPts', b.pts, state, name)
    bump(r, 'playerReb', b.oreb + b.dreb, state, name)
    bump(r, 'playerAst', b.ast, state, name)
  }
  if (f.kind === 'regular') {
    const st = state.leagues[f.league].standings[c.teamId]
    if (st && st.streak > 0) bump(r, 'streak', st.streak, state, '')
  }
}

/** 週のまとめ: 前と比べて更新された記録（はじめて記録が付いたもの（前がない）は出さない） */
export function newClubRecords(before: ClubRecords | undefined, after: ClubRecords | undefined): { k: keyof ClubRecords; r: ClubRecord }[] {
  if (!after) return []
  return (Object.keys(CLUB_RECORD_LABEL) as (keyof ClubRecords)[]).flatMap((k) => {
    const a = after[k]
    const b = before?.[k]
    return a && b && a.v > b.v ? [{ k, r: a }] : []
  })
}
