/**
 * 施設の運営（2026-11-15。ユーザーの「施設運営もやりたい」。お金は「使い道が中心」）。
 *   施設の古さ: 施設ごとの状態（0〜100）。シーズンの終わりに減り（運営の段で速さが変わる）、60 を切ると効き目が落ちる（0 で 7 割）。
 *     改修すると 100 に戻る（費用はいまの Lv の建設費の 3 割・その場で）。工事で Lv を上げると新しくなる（100）。
 *   運営の段: 施設ごとに 節約（維持費 ×0.7・効き目 ×0.92・古くなるのが速い）／ふつう／充実（維持費 ×1.4・効き目 ×1.06・古くなりにくい）。
 *   アリーナの貸し出し: ホームの試合のない週に、コンサートや展示会でアリーナを貸す（しない・少し・たくさん）。
 *     収入は席数で決まり、貸すたびにコートの状態が落ちる（ホームの試合のある週と、貸さない週に戻る）。コートの状態が悪いとケガが増える。
 *   施設の効き目を読むところは facLv（Lv × 状態 × 運営の段）を使う。
 */
import { FACILITY_DEFS, FACILITY_IDS, facilityCost } from '../data/club'
import type { FacilityId } from '../models/club'
import type { GameState } from '../models/game'
import type { LeagueId } from '../models/league'
import { clubTeam, currentLedger } from './manage'

export const OPS_LEVELS = [
  { name: '節約', upkeep: 0.7, effect: 0.92, aging: 18 },
  { name: 'ふつう', upkeep: 1, effect: 1, aging: 12 },
  { name: '充実', upkeep: 1.4, effect: 1.06, aging: 7 },
] as const

export const RENTAL_LEVELS = [
  { name: 'しない', events: 0, wear: 0 },
  { name: '少し', events: 1, wear: 7 },
  { name: 'たくさん', events: 2, wear: 14 },
] as const

/** 1 回の貸し出しの 1 席あたりの収入（万円） */
const RENT_PER_SEAT: Partial<Record<LeagueId, number>> = { JBL3: 0.02, JBL2: 0.025, JBL1: 0.03, NBA: 0.12 }

/** 施設の状態（0〜100。なければ 100） */
export const facCond = (state: GameState, id: FacilityId) => state.club!.facilityCond?.[id] ?? 100
/** 施設の運営の段（0 節約・1 ふつう・2 充実） */
export const facOps = (state: GameState, id: FacilityId) => state.club!.facilityOps?.[id] ?? 1

/** 状態による効き目の倍率（60 から下で落ちて、0 で 0.7） */
export function condFactor(cond: number): number {
  return cond >= 60 ? 1 : 0.7 + (0.3 * Math.max(0, cond)) / 60
}

/** 効き目に使う施設の Lv（Lv × 状態 × 運営の段。小数） */
export function facLv(state: GameState, id: FacilityId): number {
  const lv = state.club!.facilities[id]
  if (!lv) return 0
  return lv * condFactor(facCond(state, id)) * OPS_LEVELS[facOps(state, id)].effect
}

/** 施設 1 つの毎年の維持費（万円。manage.ts の upkeepOf と同じ式に運営の段を掛ける） */
export function facUpkeep(state: GameState, id: FacilityId): number {
  const lv = state.club!.facilities[id]
  return lv ** 1.4 * 110 * OPS_LEVELS[facOps(state, id)].upkeep
}

/** 改修の費用（いまの Lv の建設費の 3 割） */
export function renovateCost(state: GameState, id: FacilityId): number {
  const lv = state.club!.facilities[id]
  return lv > 0 ? Math.round(facilityCost(id, lv) * 0.3) : 0
}

export function renovate(state: GameState, id: FacilityId): string | null {
  const c = state.club!
  const cost = renovateCost(state, id)
  if (!cost) return '施設がない'
  if (facCond(state, id) >= 100) return '新しいまま'
  if (c.money < cost) return '資金が足りない'
  c.money -= cost
  currentLedger(state).build += cost
  ;(c.facilityCond ??= {})[id] = 100
  state.news.push({ season: state.season, week: state.week, text: `${FACILITY_DEFS[id].name}を改修した` })
  return null
}

export function setFacOps(state: GameState, id: FacilityId, level: number) {
  ;(state.club!.facilityOps ??= {})[id] = Math.max(0, Math.min(2, level))
}

/** Lv を上げたら新しくなる（manage.ts の工事の完成から） */
export function facRenewed(state: GameState, id: FacilityId) {
  ;(state.club!.facilityCond ??= {})[id] = 100
}

/** シーズンの終わり: 施設が古くなる */
export function facAging(state: GameState) {
  const c = state.club!
  for (const id of FACILITY_IDS) {
    if (!c.facilities[id]) continue
    const cond = facCond(state, id)
    ;(c.facilityCond ??= {})[id] = Math.max(0, cond - OPS_LEVELS[facOps(state, id)].aging)
  }
}

/** コートの状態（0〜100。なければ 100） */
export const courtCond = (state: GameState) => state.club!.court ?? 100

/** コートの状態によるケガの倍率 */
export function courtInjuryMul(state: GameState): number {
  const v = courtCond(state)
  return v < 45 ? 1.25 : v < 70 ? 1.1 : 1
}

/** 1 回の貸し出しの収入（いまの席数・アリーナの格・部で） */
export function rentPerEvent(state: GameState): number {
  const team = clubTeam(state)
  return Math.round(team.arena.capacity * (RENT_PER_SEAT[team.league] ?? 0.02) * (0.85 + state.club!.arenaGrade * 0.06))
}

/** 毎週（clubAfterWeek から）: ホームの試合のない週なら貸し出す。収入を返す */
export function rentalWeek(state: GameState, homeGame: boolean): number {
  const c = state.club!
  const r = RENTAL_LEVELS[c.arenaRental ?? 0]
  const court = courtCond(state)
  if (homeGame || r.events === 0) {
    c.court = Math.min(100, court + 8)
    return 0
  }
  c.court = Math.max(0, court - r.wear)
  return rentPerEvent(state) * r.events
}
